mapper.select:
select r.*, u.name as user_name
from review r
left join user u on r.user_id = u.id
where r.product_id = #{productId}
  and r.status = #{status}


        and r.rating <= 3


        and r.rating = #{rating}


order by r.create_time desc

select * from review
where order_id = #{orderId} and user_id = #{userId}
limit 1
